using Godot;
using System;
using System.Linq;
using Settings=Godot.Collections.Dictionary;

public partial class ShaderWorkspaceOperations
{
    public void add_texture_parameter(Control owner,VBoxContainer parent,StringName name,Variant value)
    {
        var values=owner.Get("parameter_values").AsGodotDictionary();var expanded=owner.Get("parameter_expanded").AsGodotDictionary();bool IsExpanded()=>expanded.TryGetValue(name,out var state)&&state.AsBool();Variant Current()=>values.TryGetValue(name,out var found)?found:default;
        var noise=noise_from_parameter(value);var row=Row(parent);var slot=new ActorResourceSlot();slot.Name=name+"_texture_slot";slot.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;slot.Alignment=HorizontalAlignment.Left;row.AddChild(slot);var menu=Attach(slot,new PopupMenu());menu.AddItem("Create Noise Image",0);menu.AddItem("Load from project…",1);menu.AddItem("Load from Super Clipboard…",7);menu.AddItem("Copy to Super Clipboard",6);if(value.VariantType!=Variant.Type.Nil){menu.AddSeparator();menu.AddItem("Clear",2);}
        var current=Current();if(noise_from_parameter(current)!=null){slot.Text=(IsExpanded()?"▾  ":"▸  ")+"Noise Image";slot.TooltipText="Click to expand the generated image · right-click for options";}else if(current.VariantType==Variant.Type.String&&current.AsString().Length>0){slot.Text="▣  "+current.AsString().GetFile();slot.TooltipText=current.AsString();}else if(current.VariantType==Variant.Type.Object&&current.AsGodotObject() is Texture2D image){slot.Text="▣  "+(image.ResourceName.Length>0?image.ResourceName:"Image");}else{slot.Text="◇  Empty image";slot.TooltipText="Click to create a Noise Image or load an image from the project";}
        void Open(Vector2 at){menu.Position=(Vector2I)at;menu.Popup();}slot.Pressed+=()=>{if(noise_from_parameter(Current())!=null){expanded[name]=!IsExpanded();rebuild_parameters(owner);}else Open(slot.GetScreenPosition()+new Vector2(0,slot.Size.Y));};slot.GuiInput+=input=>{if(input is InputEventMouseButton mouse&&mouse.Pressed&&mouse.ButtonIndex==MouseButton.Right){Open(mouse.GlobalPosition);owner.GetViewport().SetInputAsHandled();}};
        slot.Set("accepts_file",Callable.From<string,bool>(path=>new[]{"png","jpg","jpeg","webp","bmp","svg","tga","hdr","exr","tres","res"}.Contains(path.GetExtension().ToLowerInvariant())));slot.Connect("file_dropped",Callable.From<string>(path=>set_parameter_image_path(owner,name,path)));
        menu.IdPressed+=id=>{if(id==0){var definition=owner.Get("registry").AsGodotObject().Call("get_object_definition",new StringName("noise_image")).AsGodotObject();if(definition!=null){expanded[name]=true;set_preview_parameter(owner,name,ActorObjectReference.from_object((ActorObjectData)definition.Call("create_object").As<Resource>()),"edit",default);rebuild_parameters(owner);}}else if(id is 1 or 7)owner.Call("_choose_parameter_texture",name,id==7);else if(id==6)owner.Call("_copy_parameter_to_clipboard",name);else if(id==2){expanded.Remove(name);set_preview_parameter(owner,name,default,"edit",default);rebuild_parameters(owner);}};
        if(noise==null||!IsExpanded())return;var panel=Attach(parent,new PanelContainer());panel.AddThemeStyleboxOverride("panel",box(new Color("0f1922"),new Color("3b5c70"),7));var contents=Column(panel,6);var preview=Attach(contents,new TextureRect {Name=name+"_noise_preview",CustomMinimumSize=new Vector2(0,110),ExpandMode=TextureRect.ExpandModeEnum.IgnoreSize,StretchMode=TextureRect.StretchModeEnum.KeepAspectCentered,Texture=Texture(noise).As<Texture2D>()});var noiseDefinition=owner.Get("registry").AsGodotObject().Call("get_object_definition",new StringName("noise_image")).As<Resource>();if(noiseDefinition==null)return;var groups=new System.Collections.Generic.Dictionary<string,VBoxContainer>();foreach(var raw in noiseDefinition.Get("properties").AsGodotArray()){var property=raw.As<Resource>();var options=property.Get("options").AsGodotDictionary();string groupName=options.TryGetValue("group",out var title)?title.AsString():"Properties";if(!groups.TryGetValue(groupName,out var group)){group=Column(contents,5);Caption(group,groupName.ToUpperInvariant(),"78cdb9");groups[groupName]=group;}add_noise_property(owner,group,name,noise,noiseDefinition,property,preview);}
    }
}
